import{_ as o,h as i,i as e,c as s,v as l,p,x as t,m as n,e as d,S as c}from"./chunks/framework.Dvtg8yj2.js";const T=JSON.parse('{"title":"相机可控长视频（至 1440p / 1 分钟）","description":"","frontmatter":{"title":"相机可控长视频（至 1440p / 1 分钟）","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/atlas-camera-controlled-video.md","filePath":"llm/atlas-camera-controlled-video.md","lastUpdated":1788454257000}'),h={name:"llm/atlas-camera-controlled-video.md"};function m(E,a,_,A,B,f){const r=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=l('<h1 id="相机可控长视频-至-1440p-1-分钟" tabindex="-1">相机可控长视频（至 1440p / 1 分钟） <a class="header-anchor" href="#相机可控长视频-至-1440p-1-分钟" aria-label="Permalink to &quot;相机可控长视频（至 1440p / 1 分钟）&quot;">​</a></h1><div class="epigraph"><p>你在导戏，而不是去拉老虎机：每一场、每一个机位都可以指定；官方展示里，小集合参考图加手绘相机路径，可以写出约一分钟、1440p 的连贯世界。</p><footer>—— 改写自 World Labs Team, Atlas, 2026</footer></div><p>文本视频模型里，机位常常写在提示词里：「缓缓升起再环绕」。提示词不是李群，模型把「crane」理解成一种运动风格，而不是一条可重复的轨迹。Atlas 把相机几何当作<a href="/llm/atlas-native-camera">原生输入</a>，参考图钉在空间上下文里，再沿用户设计的路径自回归地写出后续帧。World Labs 展示的上限是：<strong>至 1440p、约 1 分钟</strong>的相机可控视频。本篇把这条长视频能力从稀疏重建和子弹时间里拆出来，只讨论「指定轨迹 + 少图条件 → 可控长镜头」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>长镜头要同时满足三件事：内容与参考图一致、几何上沿着给定 \\(P_t\\) 走、时间上在数十秒内不崩。短视频模型可以靠一次扩散吃下十几秒；一分钟量级会碰到上下文膨胀、误差累积和分辨率算力。若相机只通过文本注入，复杂轨迹——一到三段电影运动的组合——对照模型会跟丢，因为语言没有给出每帧外参。</p><p>另一问题是控制权。随机种子决定构图时，用户只能抽卡。空间智能的目标是把构图权交还给路径：\\(P_{1:T}\\) 是用户的，模型负责在这条路径上填世界。参考图可以是一到六张（官方相机生成示例的常见范围），长镜头段落则写「少量参考图」。数量不是架构秘密，而是条件强度：图越少，路径两侧要靠先验补的越多。</p><h3 id="分辨率、时长与「原生」不是同一句话" tabindex="-1">分辨率、时长与「原生」不是同一句话 <a class="header-anchor" href="#分辨率、时长与「原生」不是同一句话" aria-label="Permalink to &quot;分辨率、时长与「原生」不是同一句话&quot;">​</a></h3><p>1440p 与约一分钟是官方展示规格，不是公开的 SLA。它说明模型被推到过这一工作点：足够长，长到普通视频扩散一次去噪很难直接铺开；足够高清，高清到不能只靠 512 再超分来假装。它不说明生成耗时、是否分段重采样、是否全程保持 1440p 潜空间、失败率或费用。写树标题把「至 1440p / 1 分钟」写进去，是为了钉死产品声称的工作点，避免和 5 秒预览短片混谈。</p><p><span class="marginnote">「像素级相机控制」是官方用语，指位姿作为几何输入而非形容词。不要理解成光流意义上的像素精度已经在所有镜头上测过。对照评测用人类评判「哪条更跟机位」，Atlas 吃原生轨迹，别人吃文本，优势随轨迹变复杂而增大——这支持接口假设，不支持「每像素外参误差为零」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>用户提供参考图像 \\(\\{I_k\\}\\) 与一条离散位姿轨迹 \\(P_{1:T}\\)。每张参考图进入空间上下文时带自己的相机；生成段按时间（也按空间位移）逐元素写出 \\(I_t\\mid I_{&lt;t},\\{I_k\\},P_{\\le t}\\)。<a href="/llm/atlas-video-as-frames">视频被当作带位姿的图像序列</a>，因此长视频不是另一种主干，而是更长的自回归序列。每一步内部仍是潜空间上的<a href="/llm/atlas-rectified-flow">rectified flow</a> 去噪，步数可换速度与质量。</p><p>空间上下文还可以把两张无关的图放到场景里的两个位置，让模型在中间「长出」走廊与门。长视频把这件事沿时间展开：路径从一幅参考走向另一幅，中间帧必须在三维里走得通，而不能只在潜空间里做二维插值。官方称这是在管理空间上下文，而不是提示词工程。</p>',12)),(e(),p(c,null,{default:t(()=>[d(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20REF%5B%22%E5%8F%82%E8%80%83%E5%9B%BE%201%E2%80%936%20%E5%BC%A0%22%5D%20--%3E%20CTX%5B%22%E7%A9%BA%E9%97%B4%E4%B8%8A%E4%B8%8B%E6%96%87%22%5D%0A%20%20PATH%5B%22%E6%89%8B%E7%BB%98%E7%9B%B8%E6%9C%BA%E8%B7%AF%E5%BE%84%20P1%3AT%22%5D%20--%3E%20CTX%0A%20%20CTX%20--%3E%20AR%5B%22%E8%87%AA%E5%9B%9E%E5%BD%92%E5%86%99%E5%87%BA%E4%B8%8B%E4%B8%80%E5%B8%A7%22%5D%0A%20%20AR%20--%3E%20DEN%5B%22%E6%BD%9C%E7%A9%BA%E9%97%B4%E5%8E%BB%E5%99%AA%22%5D%0A%20%20DEN%20--%3E%20F%5B%221440p%20%E5%B8%A7%22%5D%0A%20%20F%20--%3E%20AR%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<h3 id="为何自回归而不是一次铺满一分钟" tabindex="-1">为何自回归而不是一次铺满一分钟 <a class="header-anchor" href="#为何自回归而不是一次铺满一分钟" aria-label="Permalink to &quot;为何自回归而不是一次铺满一分钟&quot;">​</a></h3><p>一分钟 24 fps 是约 1440 帧量级，全部像素一次性扩散的显存与耦合都不可接受。自回归把问题切成「下一个元素」，已生成帧进入上下文，KV 可以缓存，这正是后文<a href="/llm/atlas-llm-serving-tricks">沿用 LLM 服务技巧</a> 的理由。代价是误差沿 \\(t\\) 积分：某一段跟丢几何，后面会在错误世界上继续走。手绘路径与关键参考图是用户侧的纠错点：可以在漂之前插入新锚点，相当于把长序列重新接地。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>相机可控的条件比文本机位硬。文本只约束运动的语义类；位姿序列约束每帧的投影</p> \\[x = \\pi(P_t X), \\]<p>同一世界点 \\(X\\) 必须沿轨迹投影到与参考图相容的位置。模型若把世界建成与 \\(\\{I_k\\}\\) 一致的潜在三维，跟机位就是投影问题；若只把帧当成二维动画，复杂轨迹会露馅。这解释了为何官方强调优势随轨迹复杂度上升：文本对照在「pan」这种单子上或许能蒙，组合 crane 与 truck 时语言条件不够用。</p><p>长时一致性来自空间锚而不是来自光流平滑。参考图在三维里的位置不随 \\(t\\) 漂，后续帧是对同一上下文的查询。这与纯时间注意力的视频模型不同：后者的记忆是「刚才那一帧长什么样」，前者的记忆是「那个沙发在世界的哪里」。沙发可以在画面里变大变小，只要 \\(P_t\\) 在靠近。失败模式也因此不同：不是简单运动模糊，而是世界结构在长程上被改写——门换边、建筑镜像、文本标识漂移。</p><p><span class="marginnote">展示用的一分钟 1440p 片段经过网页压缩；官方写明页面上其余视频为了加载被压缩，该长镜头按 1440p 生成。阅读演示时要把「生成分辨率」和「页面播放分辨率」分开，否则会低估或高估产品工作点。</span></p><h3 id="少图条件如何撑起一分钟" tabindex="-1">少图条件如何撑起一分钟 <a class="header-anchor" href="#少图条件如何撑起一分钟" aria-label="Permalink to &quot;少图条件如何撑起一分钟&quot;">​</a></h3><p>一分钟路径会扫过参考图里根本不存在的表面。模型必须持续想象，同时不丢掉已锚定的物体身份。空间上下文管理包括：让参考图在序列中保持可被注意力读到，以及在路径关键点放置额外图像。公开材料没有给出最大帧数、滑动窗口或检索策略；RTFM 曾用「上下文杂耍」在实时设定下检索近邻帧，但 Atlas 并未声明沿用同一机制。工程上只能假定：一分钟是演示可达，不是「任意更长只要继续 decode」。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>至 1440p / 约 1 分钟是展示上限，不是保证所有风格、所有场景都能一次出片。生成时间、卡数、是否蒸馏步数，均未写进模型卡。内容漂移、标识不稳定、路径穿模、画外结构乱编，都是长镜头的预期风险，官方未给量化失败率。对照实验的不对称接口（原生位姿 vs 文本）说明评测目标是跟机，不是美学总分；选片、种子与时长分布也未公开。</p><p>不要把长视频写成物理仿真。物体可以看起来沿路径稳定，不意味着质量、碰撞和光照传输是对的。动态主体、口型、音频不在这条能力的中心；Atlas 可以做图像与 360 全景，但相机可控长视频的卖点是空间控制。早鸟访问下，外部无法验证「一分钟」是单次自回归还是分段拼接后选的最好一条。产品接入时应按「可指定轨迹的生成器」来用，并在关键帧上做人审。</p><p><span class="marginnote">树标题把分辨率与时长写死，是为了防止和 RTFM 的实时低延迟出帧、和 Marble 的可导航溅射世界混成同一个「世界模型视频」。三者都能「看世界」，但工作点分别是：离线高清可控长镜头、交互帧率、可导出三维资产。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Atlas 用原生相机轨迹加少量参考图生成新视角视频，展示工作点为至 1440p、约 1 分钟。</li><li>控制来自李群意义上的 \\(P_t\\)，不是提示词里的电影术语。</li><li>长镜头采用带位姿帧的自回归写出；空间上下文让参考图在三维里保持锚点。</li><li>「像素级控制」指接口精度，不等于已公布的外参误差为零。</li><li>一分钟尺度会累积几何与身份漂移，需靠加锚点与人审，而不是假定无限稳。</li><li>该规格是演示可达点，不包含延迟、费用与成功率承诺。</li><li>出处：World Labs Team，<em>Atlas: A World Model for Spatial Intelligence</em>，World Labs Blog，2026。</li></ul>',16))])}const b=o(h,[["render",m]]);export{T as __pageData,b as default};
